const entries = draft.content.split(/\r\n|[\n\r]/).map(line => line.trim()).filter(Boolean);
if (!entries.length) { context.fail('The draft has no items to add.'); }
else {
  const lists = Draft.query('', 'all', ['list']).filter(item => item.uuid !== draft.uuid);
  const choice = SelectPrompt.create(); choice.title = 'Choose a list';
  lists.forEach(item => choice.addItem(item.uuid, item.displayTitle));
  choice.addItem('__new__', 'Create new list');
  if (!choice.show()) { context.cancel(); }
  else {
    let destination;
    if (choice.selectedItem.id === '__new__') {
      const prompt = Prompt.create(); prompt.title = 'Create a list';
      prompt.addTextField('name', 'List name', ''); prompt.addButton('Create');
      if (!prompt.show()) { context.cancel(); }
      else {
        const name = String(prompt.fieldValues.name || '').trim();
        if (!name || /[\r\n]/.test(name)) { context.fail('Enter a name on one line.'); }
        else {
          destination = Draft.create(); destination.content = '# ' + name + '\n';
          destination.addTag('list'); destination.isArchived = true;
        }
      }
    } else { destination = Draft.find(choice.selectedItem.id); }
    if (destination) {
      const separator = destination.content && !destination.content.endsWith('\n') ? '\n' : '';
      destination.content += separator + entries.map(item => '- [ ] ' + item).join('\n');
      destination.update();
    }
  }
}
